// Illustrated profile-picture avatars for the app's three named accounts,
// keyed by role — used wherever a person's initials-circle would otherwise
// show (approval table, document History popup, top-right user badge).
// Matched against USERS by name in personAvatarFor(); anyone not in USERS
// still falls back to a plain initials circle, so this never breaks for
// other/future names.
const PERSON_AVATARS = {
  QM: 'data:image/jpeg;base64,',
  LM: 'data:image/jpeg;base64,',
  DC: 'data:image/jpeg;base64,', // DC account also covers the TM/reviewer function — see assignedReviewerName()
};
function personAvatarFor(name){
  if(!name) return null;
  const u = USERS.find(x=>x.name===name);
  return u ? PERSON_AVATARS[u.role] : null;
}
// Renders either the matched illustrated avatar (as a photo-fill circle)
// or the existing plain initials circle, using whatever CSS class the
// call site already relies on for shape/position (row-avatar, hist-avatar,
// ...) but with an explicit inline size so it renders bigger than that
// class's own (smaller) default, consistently across every feature.
function avatarNodeHTML(name, cls, fallbackText, size){
  const px = size || 42;
  const sizeStyle = `width:${px}px; height:${px}px; min-width:${px}px; border-radius:50%; font-size:${Math.round(px*0.38)}px;`;
  const src = personAvatarFor(name);
  if(src) return `<div class="${cls}" style="${sizeStyle} background-image:url('${src}'); background-size:cover; background-position:center;"></div>`;
  return `<div class="${cls}" style="${sizeStyle} display:flex; align-items:center; justify-content:center;">${fallbackText}</div>`;
}
// With exactly one account per role (DC/QM/LM), the reviewer and approver
// for any new/revision request can be worked out immediately instead of
// waiting for someone to actually click through the workflow:
//  - approver is always the LM account (only one LM login exists)
//  - reviewer is the TM function, which the DC account holds concurrently
//    (DC's other duties — posting links, deleting, distributing — are
//    separate document-control tasks, not the review itself). So the
//    default reviewer for every document is the DC/TM account. The only
//    time it's someone else is when DC/TM is the one requesting — a
//    reviewer can't be the requester — in which case QM reviews instead.
//    DC still retains the ability to act on any step regardless (see
//    isDC() elsewhere), this only affects the name shown as "assigned".
// This only sets the *expected* name so it displays right away in the
// Approval list/detail; the actual review/approve click still overwrites
// it with whoever really performed that step (see the approve button
// handler), which normally just reconfirms the same name.
function lmAccountName(){
  const lm = USERS.find(u=>u.role==='LM');
  return lm ? lm.name : '';
}
function assignedReviewerName(requesterName){
  const dc = USERS.find(u=>u.role==='DC');
  const qm = USERS.find(u=>u.role==='QM');
  if(dc && dc.name===requesterName) return qm ? qm.name : '';
  return dc ? dc.name : (qm ? qm.name : '');
}
let currentUser = null;
const SESSION_KEY = 'mpir_iso17025_session';
function tryRestoreSession(){
  try{
    const raw = localStorage.getItem(SESSION_KEY);
    if(!raw) return;
    const saved = JSON.parse(raw);
    const match = USERS.find(u=>u.id===saved.id);
    if(match) currentUser = { id:match.id, name:match.name, role:match.role };
  } catch(e){ /* ignore corrupt/blocked storage */ }
}
function saveSession(){
  try{ localStorage.setItem(SESSION_KEY, JSON.stringify({ id: currentUser.id })); } catch(e){}
}
function clearSession(){
  try{ localStorage.removeItem(SESSION_KEY); } catch(e){}
  currentUser = null;
}
function isDC(){ return !!currentUser && currentUser.role==='DC'; }
function currentActorName(){ return currentUser ? currentUser.name : 'ไม่ระบุ'; }

// ============================================================
// I18N TRANSLATION ENGINE (TH <-> EN)
// Full-app runtime translator. Instead of hand-editing every one of
// the render*() functions (which build their HTML as Thai-language
// template literals), we intercept the two DOM APIs those functions
// ultimately funnel through — .innerHTML and .textContent — plus the
// native confirm()/alert() dialogs, and translate any *visible* text
// after it lands in the DOM. Values used for app logic (option
// "value" attributes, data-* attributes, comparisons against
// APPROVAL_STATUS / STATUS_FLOW etc.) are never touched, because we
// only rewrite text NODES (and a couple of safe, display-only
// attributes) — never element attributes that carry real data.
// This means every page/modal/panel gets translated automatically,
// including ones added later, with no per-view code changes needed.
// ============================================================
