const I18N_KEYS_SORTED = Object.keys(I18N_DICT).sort((a,b)=> b.length - a.length);
const THAI_RE = /[\u0E00-\u0E7F]/;
function translateText(str){
  if(uiLang !== 'en' || typeof str !== 'string' || !THAI_RE.test(str)) return str;
  let out = str;
  for(let i=0;i<I18N_KEYS_SORTED.length;i++){
    const th = I18N_KEYS_SORTED[i];
    if(out.indexOf(th) !== -1) out = out.split(th).join(I18N_DICT[th]);
  }
  return out;
}
function translateDomSubtree(root){
  if(uiLang !== 'en' || !root || !root.querySelectorAll) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
  const nodes = [];
  let n;
  while((n = walker.nextNode())) nodes.push(n);
  nodes.forEach(node=>{
    if(THAI_RE.test(node.nodeValue)) node.nodeValue = translateText(node.nodeValue);
  });
  root.querySelectorAll('[placeholder]').forEach(elx=>{
    if(THAI_RE.test(elx.placeholder)) elx.placeholder = translateText(elx.placeholder);
  });
  root.querySelectorAll('[title]').forEach(elx=>{
    if(THAI_RE.test(elx.title)) elx.title = translateText(elx.title);
  });
}
(function installI18nHooks(){
  const ihDesc = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML')
    || Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'innerHTML');
  Object.defineProperty(Element.prototype, 'innerHTML', {
    configurable: true,
    enumerable: ihDesc.enumerable,
    get(){ return ihDesc.get.call(this); },
    set(html){
      // set the REAL (untranslated) markup first so data-*/value attrs
      // stay exactly as the app logic expects, then translate the text
      // nodes that resulted from it.
      ihDesc.set.call(this, html);
      if(uiLang === 'en') translateDomSubtree(this);
    }
  });
  const tcDesc = Object.getOwnPropertyDescriptor(Node.prototype, 'textContent');
  Object.defineProperty(Node.prototype, 'textContent', {
    configurable: true,
    enumerable: tcDesc.enumerable,
    get(){ return tcDesc.get.call(this); },
    set(text){ tcDesc.set.call(this, translateText(text)); }
  });
  const nativeConfirm = window.confirm.bind(window);
  window.confirm = (msg)=> nativeConfirm(translateText(msg));
  const nativeAlert = window.alert.bind(window);
  window.alert = (msg)=> nativeAlert(translateText(msg));
})();

