// Turns "สรุปประชุม_ทบทวนฝ่ายบริหาร-มค69.pdf" into "สรุปประชุม ทบทวนฝ่ายบริหาร มค69"
// — best-effort cleanup only, user can still edit the title field after.
function fileNameToTitleGuess(fileName){
  const noExt = fileName.replace(/\.[a-zA-Z0-9]{1,6}$/, '');
  return noExt.replace(/[_\-]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function wireArchiveDropZone(){
  const zone = document.getElementById('archiveDropZone');
  if(!zone) return;
  const statusEl = document.getElementById('archiveDropStatus');
  const titleInput = document.getElementById('archiveTitle'); // absent in verify mode
  const highlightOn = ()=>{ zone.style.borderColor = 'var(--green-600, #1a7f5a)'; zone.style.background = 'var(--bg)'; };
  const highlightOff = ()=>{ zone.style.borderColor = ''; zone.style.background = ''; };
  ['dragenter','dragover'].forEach(evt=>{
    zone.addEventListener(evt, e=>{ e.preventDefault(); e.stopPropagation(); highlightOn(); });
  });
  ['dragleave','dragend'].forEach(evt=>{
    zone.addEventListener(evt, e=>{ e.preventDefault(); e.stopPropagation(); highlightOff(); });
  });
  zone.addEventListener('drop', e=>{
    e.preventDefault(); e.stopPropagation(); highlightOff();
    const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
    if(!file) return;

    // Fill in the document title from the file name, if there's a title
    // field on this screen and it's currently empty.
    if(titleInput && !titleInput.value.trim()){
      titleInput.value = fileNameToTitleGuess(file.name);
      titleInput.dispatchEvent(new Event('input')); // triggers clause suggestion
    }

    // Open the real SharePoint form automatically — file uploads can't be
    // handed off across domains by code, so the user still has to drag
    // (or attach) the file into that form themselves.
    window.open(ARCHIVE_REQUEST_FORM_LINK, '_blank', 'noopener');

    if(statusEl){
      statusEl.style.display = 'block';
      statusEl.textContent = `📎 ลากไฟล์ "${file.name}" ไปวางที่ปุ่ม "+ เพิ่มสิ่งที่แนบมา" ในแท็บฟอร์มที่เพิ่งเปิดขึ้นได้เลย`;
    }
  });
}
function wireArchiveModalControls(){
  const backdrop = document.getElementById('archiveModalBackdrop');
  if(!backdrop) return;
  document.getElementById('archiveModalCloseBtn').addEventListener('click', closeArchiveModal);
  document.getElementById('archiveModalCancelBtn').addEventListener('click', closeArchiveModal);
  backdrop.addEventListener('click', e=>{ if(e.target===backdrop) closeArchiveModal(); });

  // Drag-and-drop shortcut: dropping a file here doesn't upload it (this
  // app has no file storage of its own — the real file always has to land
  // on the external SharePoint form), but it removes the two most
  // clicky/typy steps: opening the form and typing the document name.
  wireArchiveDropZone();

  // live clause suggestion, based on the title — same keyword matcher used
  // for regular documents
  const archiveTitleInput = document.getElementById('archiveTitle');
  const archiveClauseSel = document.getElementById('archiveClause');
  const archiveClauseHint = document.getElementById('archiveClauseSuggest');
  function refreshArchiveClauseSuggest(){
    if(!archiveClauseHint) return;
    const name = archiveTitleInput ? archiveTitleInput.value.trim() : '';
    const suggested = suggestClause(name);
    if(suggested && archiveClauseSel && archiveClauseSel.value !== suggested){
      archiveClauseHint.innerHTML = `💡 แนะนำ: ${clauseLabel(suggested)} <button type="button" class="suggest-accept" id="acceptArchiveClauseSuggest">ใช้คำแนะนำนี้</button>`;
      const btn = document.getElementById('acceptArchiveClauseSuggest');
      if(btn) btn.addEventListener('click', ()=>{ archiveClauseSel.value = suggested; refreshArchiveClauseSuggest(); });
    } else {
      archiveClauseHint.innerHTML = '';
    }
  }
  if(archiveTitleInput) archiveTitleInput.addEventListener('input', refreshArchiveClauseSuggest);
  refreshArchiveClauseSuggest();

  const saveBtn = document.getElementById('archiveModalSaveBtn');
  if(!saveBtn) return;
  saveBtn.addEventListener('click', async ()=>{
    const mode = state.archiveModal.mode;
    const errEl = document.getElementById('archiveModalError');

    if(mode==='verify'){
      if(!isDC()) return; // defense in depth
      const verifier = currentActorName();
      const a = ARCHIVE_ITEMS.find(x=>x.id===state.archiveModal.id);
      if(!a) return;
      const linkInput = document.getElementById('archiveVerifyLink');
      if(linkInput) a.link = linkInput.value.trim();
      a.status = 'ยืนยันแล้ว';
      a.verifiedBy = verifier;
      a.verifiedAt = Date.now();
      closeArchiveModal();
      render();
      await persistArchive();
      render();
      return;
    }

    const title = document.getElementById('archiveTitle').value.trim();
    const category = document.getElementById('archiveCategory').value.trim();
    const clauseSel = document.getElementById('archiveClause');
    const clause = clauseSel ? clauseSel.value : '';
    const linkInput = document.getElementById('archiveLink');
    const uploadedBy = currentActorName();
    const dateInput = document.getElementById('archiveDate');
    const dateVal = dateInput ? dateInput.value : '';
    const uploadedAt = dateVal ? new Date(dateVal+'T00:00:00').getTime() : Date.now();
    if(!title){ errEl.textContent='กรอกชื่อเอกสารให้ครบ'; errEl.style.display='block'; return; }
    const cancelledInput = document.getElementById('archiveCancelledDate');
    const cancelledDate = cancelledInput ? (cancelledInput.value ? new Date(cancelledInput.value+'T00:00:00').getTime() : null) : undefined;
    const cancelledRevInput = document.getElementById('archiveCancelledRev');
    const cancelledRev = cancelledRevInput ? (cancelledRevInput.value.trim() || null) : undefined;

    if(mode==='new'){
      // non-DC submitters never see the link field (they fill the external
      // form instead) — link stays blank until DC verifies and pastes it in
      const link = linkInput ? linkInput.value.trim() : '';
      ARCHIVE_ITEMS.push({
        id: 'ARC-' + Date.now().toString(36) + Math.random().toString(36).slice(2,6),
        title, category, clause, link, uploadedBy, uploadedAt,
        cancelledDate: cancelledDate ?? null,
        cancelledRev: cancelledRev ?? null,
        status:'รอตรวจสอบ', verifiedBy:null, verifiedAt:null,
      });
    } else {
      const a = ARCHIVE_ITEMS.find(x=>x.id===state.archiveModal.id);
      if(a){
        a.title = title; a.category = category; a.clause = clause; a.uploadedBy = uploadedBy; a.uploadedAt = uploadedAt;
        if(linkInput) a.link = linkInput.value.trim(); // only present for DC — non-DC editors leave the existing link untouched
        if(cancelledDate !== undefined) a.cancelledDate = cancelledDate;
        if(cancelledRev !== undefined) a.cancelledRev = cancelledRev;
      }
    }
    closeArchiveModal();
    render();
    await persistArchive();
    render();
  });
}

