function viewDocDetail(docId){
  const d = DOCUMENTS.find(x=>x.id===docId);
  if(!d) return `<div class="panel">${emptyState('ไม่พบเอกสาร','This document may have been deleted.')}</div>`;
  return `
  <div class="crumb" data-back="1">‹ Back</div>
  <div class="panel">
    ${docDetailContent(d)}
  </div>`;
}
