// ============================================================
// IMPORT MASTER LIST — UI entry point for runMasterListImport()
// (see the MASTER LIST IMPORT section below for the merge logic).
// DC-only, matching the other admin-only tools on this page.
// ============================================================
function findCorruptedRevDocs(){
  // Data-repair helper for the d.rev-overwrite bug in applyMasterListRow
  // (fixed above, but already-saved documents can still carry the bad
  // value): a document with an in-progress revision request whose rev
  // was clobbered back down to match d.lastRequestFrom shows up as e.g.
  // "Rev.1 → 1" in the Approval queue instead of "Rev.1 → 2". Detect it
  // the same way it displays: lastRequestType is 'revision', the request
  // is still pending, and d.rev equals d.lastRequestFrom (or is missing).
  return DOCUMENTS.filter(d=>
    d.lastRequestType==='revision'
    && ['ร่าง','รอทบทวน','รออนุมัติ'].includes(d.approvalStatus)
    && d.lastRequestFrom
    && (d.rev===d.lastRequestFrom || !d.rev)
  );
}
async function repairCorruptedRevNumbers(){
  const targets = findCorruptedRevDocs();
  if(!targets.length) return { ok:true, fixed:0 };
  const actor = currentActorName();
  const now = Date.now();
  targets.forEach(d=>{
    const wrongRev = d.rev;
    d.rev = nextRevNumber(d.lastRequestFrom);
    d.comments = d.comments || [];
    d.comments.push({ by:actor, text:`ซ่อมแซมเลข Rev. อัตโนมัติ — แก้จาก Rev.${wrongRev||'-'} (ผิดพลาดจากการนำเข้ารายการเอกสารหลักทับคำขอปรับปรุงที่ค้างอยู่) เป็น Rev.${d.rev}`, time: now });
    d.lastUpdated = now;
  });
  await persistDocs();
  return { ok:true, fixed: targets.length, ids: targets.map(d=>d.id) };
}
function viewImportMasterListPanel(){
  if(!isDC()) return '';
  const hasList = typeof MASTER_LIST !== 'undefined';
  const total = hasList ? MASTER_LIST.length : 0;
  const cancelledCount = hasList ? MASTER_LIST.filter(r=>r.note==='ยกเลิก').length : 0;
  const activeRows = hasList ? MASTER_LIST.filter(r=>r.note!=='ยกเลิก') : [];
  const existingIds = new Set(DOCUMENTS.map(d=>d.id));
  const newCount = activeRows.filter(r=>!existingIds.has(r.id)).length;
  const updateCount = activeRows.length - newCount;
  const corrupted = findCorruptedRevDocs();
  return `
  <div class="panel" style="margin-top:20px;">
    <div class="panel-head"><div class="panel-title">นำเข้ารายการเอกสารหลัก (Import Master List)</div></div>
    ${hasList ? `
    <div style="font-size:12.5px; color:var(--ink-700); margin-bottom:14px;">
      นำเข้าเอกสารจาก <code>masterlist.js</code> (${total} รายการ) เข้าสู่ทะเบียนเอกสาร — <b>ไม่ผ่านขั้นตอนอนุมัติในระบบ</b> เอกสารที่มีสถานะ "ควบคุม" "แจกจ่าย" "สนับสนุน" หรือ "ยกเลิก" ในรายการหลักจะถูกตั้งเป็น <b>"อนุมัติแล้ว"</b> ทันที โดยใช้ <b>วันที่จัดทำ</b> และ <b>วันที่ประกาศใช้</b> ตามที่ระบุไว้ในรายการหลักของแต่ละเอกสาร รหัสที่ตรงกับเอกสารเดิม (${updateCount} รายการ) จะถูกอัปเดตข้อมูล ส่วนรหัสใหม่ (${newCount} รายการ) จะถูกเพิ่มเข้าทะเบียน<br>
      เอกสารที่มีสถานะ <b>"ยกเลิก"</b> (${cancelledCount} รายการ) จะ<b>ไม่แสดงในรายการเอกสารเลย</b> — จะถูกย้ายไปไว้ที่ คลังเอกสาร → โฟลเดอร์ "${CANCELLED_ARCHIVE_CATEGORY}" แทน
    </div>
    <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap;">
      <button class="btn primary" id="btnImportMasterList">${ic('plus')} นำเข้ารายการเอกสารหลัก (${total} รายการ)</button>
      <span id="importMlStatus" style="font-size:12px; color:var(--ink-500);"></span>
    </div>` : `
    <div style="font-size:12.5px; color:var(--ink-700);">ไม่พบไฟล์ <code>masterlist.js</code> — ตรวจสอบว่าไฟล์นี้ถูกโหลดในหน้าเว็บแล้ว</div>`}
    ${corrupted.length ? `
    <div class="dp-divider" style="margin:16px 0;"></div>
    <div style="font-size:12.5px; color:var(--red-700,#b42318); margin-bottom:10px;">
      พบเอกสาร <b>${corrupted.length} รายการ</b> ที่เลข Rev. ผิดพลาดจากการนำเข้ารายการเอกสารหลักทับคำขอปรับปรุงที่ค้างอยู่ (เช่น "Rev.1 → 1" แทนที่จะเป็น "Rev.1 → 2"): ${corrupted.map(d=>d.id).join(', ')}
    </div>
    <button class="btn danger" id="btnRepairRevNumbers">${ic('history')} ซ่อมแซมเลข Rev. ที่ผิดพลาด (${corrupted.length} รายการ)</button>
    <span id="repairRevStatus" style="font-size:12px; color:var(--ink-500); margin-left:10px;"></span>` : ''}
  </div>`;
}

// ============================================================
// WATERMARK TOOL — open to every logged-in role. Whoever uses it uploads a
// PDF and the app stamps ONE centered diagonal watermark per page reading
// "CONTROLLED DOCUMENT — Issued by: <user's role> (<user's name>) |
// Issue date: <today>", entirely in the browser, then triggers a download.
// The uploaded/output PDF is never stored anywhere — only a log entry
// (document ID, who, when) is kept, so anyone can see how many controlled
// copies of a document have been issued without keeping the files
// themselves.
// ============================================================
function watermarkCountsByDoc(){
  const counts = {};
  WATERMARK_LOG.forEach(e=>{
    counts[e.docId] = counts[e.docId] || { downloaded:0, distributed:0, recalled:0, entries:[] };
    const c = counts[e.docId];
    if(e.type === 'distribute'){
      c.distributed++;
      // recall only applies to distributed copies — a plain download never
      // needs to be "recalled" since it wasn't handed to anyone
      if(e.recalled) c.recalled++;
    } else {
      c.downloaded++;
    }
    c.entries.push(e);
  });
  return counts;
}
function viewWatermarkTool(){
  const counts = watermarkCountsByDoc();
  const docIds = Object.keys(counts).sort();
  return `
  <div class="panel">
    <div class="panel-head"><div class="panel-title">ลายน้ำเอกสาร (Watermark PDF)</div></div>
    <div style="font-size:12.5px; color:var(--ink-700); margin-bottom:14px;">
      อัปโหลดไฟล์ PDF แล้วระบบจะติดลายน้ำพาดขวางกลางหน้าในทุกหน้า 2 บรรทัด: <b>"CONTROLLED DOCUMENT"</b> (ตัวหนา ขนาด 36) และ "Issued by ${currentUser ? (ROLE_LABEL[currentUser.role]||currentUser.role) : '[ตำแหน่งเต็ม]'} (${currentUser ? currentUser.name : '[ชื่อเต็ม]'}) | Issue date: ${fmtDate(Date.now())}" (ตัวปกติ ขนาด 32) พร้อมแนบ<b>ทะเบียนประวัติเอกสาร</b>ต่อท้ายไฟล์ให้อัตโนมัติ (ถ้ารหัสเอกสารตรงกับเอกสารในระบบและมีประวัติแล้ว) แล้วดาวน์โหลดไฟล์เดียวให้ทันที — <b>ไม่มีการเก็บไฟล์ไว้ในระบบ</b> เก็บแค่ทะเบียนสำเนาที่แจกจ่ายไป (ใคร วันที่ ให้ใคร) เพื่อให้เรียกคืนได้ในอนาคตหากจำเป็น
    </div>
    <div class="field"><label>รหัสเอกสาร</label>
      <select id="wmDocId">
        <option value="">— เลือกเอกสาร —</option>
        ${DOCUMENTS.slice().sort((a,b)=> (a.id||'').localeCompare(b.id||'')).map(d=>`<option value="${escapeHtml(d.id)}">${escapeHtml(d.id)}${d.name ? ' — ' + escapeHtml(d.name) : ''}</option>`).join('')}
      </select>
    </div>
    <div class="field"><label>ไฟล์ PDF</label><input type="file" id="wmFile" accept="application/pdf"></div>
    <div class="field"><label>ประเภท</label>
      <select id="wmType">
        <option value="download">ดาวน์โหลด (ใช้เอง — ไม่ต้องเรียกคืน)</option>
        <option value="distribute">แจกจ่าย (ให้ผู้อื่น — ต้องเรียกคืนได้)</option>
      </select>
    </div>
    <div class="field" id="wmRecipientField" style="display:none;"><label>แจกจ่ายให้</label><input id="wmRecipient" placeholder="เช่น ทีมประกันคุณภาพ, ผู้ตรวจติดตาม"></div>
    <div class="field-error" id="wmError" style="display:none;"></div>
    <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap;">
      <button class="btn primary" id="btnWatermark">${ic('doc')} ติดลายน้ำและดาวน์โหลด</button>
      <button class="btn ghost" id="btnWmManualOpen">${ic('plus')} เพิ่มบันทึกแจกจ่ายด้วยตนเอง</button>
      <span id="wmStatus" style="font-size:12px; color:var(--ink-500);"></span>
    </div>
    <div style="font-size:11px; color:var(--ink-500); margin-top:6px;">ใช้ปุ่ม "เพิ่มบันทึกแจกจ่ายด้วยตนเอง" เมื่อแจกจ่ายสำเนาที่พิมพ์ไว้แล้วนอกระบบ (เช่น แจกในที่ประชุม) โดยไม่ต้องอัปโหลดไฟล์ซ้ำ</div>

    <div style="margin-top:22px; padding-top:18px; border-top:1px solid var(--line);">
      <div style="font-size:12.5px; font-weight:800; color:var(--ink-900); margin-bottom:10px;">ทะเบียนสำเนา (ดาวน์โหลด ${WATERMARK_LOG.filter(e=>e.type!=='distribute').length} · แจกจ่าย ${WATERMARK_LOG.filter(e=>e.type==='distribute').length} ฉบับ จาก ${docIds.length} เอกสาร)</div>
      ${docIds.length ? `<div class="table-wrap" style="overflow-x:auto;"><table class="dtable">
        <thead><tr><th>รหัสเอกสาร</th><th>ดาวน์โหลด</th><th>แจกจ่ายแล้ว</th><th>เรียกคืนแล้ว</th><th>คงเหลือนอกระบบ</th><th>ล่าสุด</th><th></th></tr></thead>
        <tbody>
          ${docIds.map(id=>{
            const c = counts[id];
            // "recall" and "outstanding" only make sense for copies that were
            // actually handed to someone — plain downloads are excluded
            const outstanding = c.distributed - c.recalled;
            const last = c.entries.slice().sort((a,b)=>b.at-a.at)[0];
            return `
          <tr data-wm-toggle="${id}" style="cursor:pointer;">
            <td class="mono" style="white-space:nowrap;">${id}</td>
            <td>${c.downloaded}</td>
            <td>${c.distributed}</td>
            <td>${c.recalled}</td>
            <td>${outstanding>0 ? `<b style="color:var(--amber-600);">${outstanding}</b>` : outstanding}</td>
            <td>${last ? `${last.by} · ${fmtDateTime(last.at)}` : '—'}</td>
            <td style="white-space:nowrap;">${isDC() ? `<button data-wm-del-doc="${id}" class="del" title="ลบทะเบียนสำเนาของเอกสารนี้ทั้งหมด" style="margin-right:6px;">${ic('trash')}</button>` : ''}${ic('chevronDown','sm-icon')}</td>
          </tr>
          <tr class="wm-detail-row" data-wm-detail="${id}" style="display:${state.wmExpandedDoc===id?'table-row':'none'};"><td colspan="7">
            ${c.entries.slice().sort((a,b)=>b.at-a.at).map(e=>{
              const isDistribute = e.type === 'distribute';
              return `
            <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; padding:6px 0; border-bottom:1px solid var(--line);">
              <div style="font-size:11.5px; color:var(--ink-700);">
                <span style="font-weight:700; color:${isDistribute ? 'var(--amber-600)' : 'var(--ink-500)'};">${isDistribute ? 'แจกจ่าย' : 'ดาวน์โหลด'}</span>
                · ${e.by} — ${fmtDateTime(e.at)}
                ${e.recipient ? ` · ให้: ${e.recipient}` : ''}
                ${e.manual ? ` <span style="color:var(--amber-600); font-weight:700;">(บันทึกด้วยตนเอง${e.note ? ': '+e.note : ''})</span>` : ''}
                ${isDistribute && e.recalled ? `<br><span style="color:var(--green-600); font-weight:700;">✓ เรียกคืนแล้ว ${fmtDateTime(e.recalledAt)} โดย ${e.recalledBy}</span>` : ''}
              </div>
              <div style="display:flex; gap:6px; flex-shrink:0;">
                ${isDistribute ? `<button class="btn ${e.recalled?'ghost':'success'}" data-wm-recall="${e.id}" style="font-size:11px; padding:5px 10px;">${e.recalled ? 'ยกเลิกการเรียกคืน' : 'ทำเครื่องหมายว่าเรียกคืนแล้ว'}</button>` : ''}
                ${isDC() ? `<button data-wm-del-entry="${e.id}" class="del" title="ลบรายการนี้" style="font-size:11px; padding:5px 10px;">${ic('trash')}</button>` : ''}
              </div>
            </div>`;
            }).join('')}
          </td></tr>`;
          }).join('')}
        </tbody>
      </table></div>` : `<div style="font-size:12.5px; color:var(--ink-500);">ยังไม่มีทะเบียนสำเนาแจกจ่าย</div>`}
    </div>
  </div>`;
}
function wmManualModal(){
  return `
  <div class="modal-backdrop" id="wmManualBackdrop">
    <div class="modal">
      <div class="modal-head"><div class="modal-title">เพิ่มบันทึกแจกจ่ายด้วยตนเอง</div><button class="modal-close" id="wmManualCloseBtn">✕</button></div>
      <div class="modal-body">
        <div style="font-size:11.5px; color:var(--ink-500); margin-bottom:14px;">สำหรับสำเนาที่พิมพ์/แจกจ่ายไปแล้วนอกระบบ (เช่น แจกในที่ประชุม) — บันทึกไว้เพื่อการนับจำนวนเท่านั้น ไม่มีการสร้างหรือเก็บไฟล์</div>
        <div class="field"><label>รหัสเอกสาร</label>
          <input id="wmManualDocId" list="wmDocIdList" placeholder="เช่น MPIR-LM-001-00 หรือพิมพ์เอง">
        </div>
        <div class="field"><label>จำนวนสำเนาที่แจกจ่าย</label>
          <input id="wmManualQty" type="number" min="1" value="1"></div>
        <div class="field"><label>แจกจ่ายให้ (ไม่บังคับ)</label>
          <input id="wmManualRecipient" placeholder="เช่น ทีมประกันคุณภาพ, ผู้ตรวจติดตาม"></div>
        <div class="field"><label>หมายเหตุ (ไม่บังคับ)</label>
          <input id="wmManualNote" placeholder="เช่น แจกในที่ประชุมทบทวนฝ่ายบริหาร"></div>
        <div class="field-error" id="wmManualError" style="display:none;"></div>
      </div>
      <div class="modal-actions">
        <button class="btn ghost" id="wmManualCancelBtn">ยกเลิก</button>
        <button class="btn primary" id="wmManualSaveBtn">บันทึก</button>
      </div>
    </div>
  </div>`;
}
function wireWmManualModal(){
  const backdrop = document.getElementById('wmManualBackdrop');
  if(!backdrop) return;
  const close = ()=>{ state.wmManualModal = false; renderModalLayer(); };
  document.getElementById('wmManualCloseBtn').addEventListener('click', close);
  document.getElementById('wmManualCancelBtn').addEventListener('click', close);
  backdrop.addEventListener('click', e=>{ if(e.target===backdrop) close(); });
  document.getElementById('wmManualSaveBtn').addEventListener('click', async ()=>{
    const errEl = document.getElementById('wmManualError');
    const docId = document.getElementById('wmManualDocId').value.trim();
    const qtyRaw = document.getElementById('wmManualQty').value;
    const qty = parseInt(qtyRaw, 10);
    const note = document.getElementById('wmManualNote').value.trim();
    const recipient = document.getElementById('wmManualRecipient').value.trim();
    if(!docId){ errEl.textContent = 'กรอกรหัสเอกสารก่อน'; errEl.style.display='block'; return; }
    if(!qty || qty < 1){ errEl.textContent = 'จำนวนสำเนาต้องเป็นตัวเลขตั้งแต่ 1 ขึ้นไป'; errEl.style.display='block'; return; }
    const actor = currentActorName();
    const now = Date.now();
    // Firestore's setDoc() rejects `undefined` field values outright — always
    // use '' (empty string) for optional text fields the user left blank,
    // never `undefined`
    for(let i=0; i<qty; i++){
      WATERMARK_LOG.push({
        id: 'WM-' + now.toString(36) + Math.random().toString(36).slice(2,7) + '-' + i,
        docId, by: actor, at: now, manual: true, note, recipient, type: 'distribute',
        recalled: false, recalledAt: null, recalledBy: null,
      });
    }
    state.wmManualModal = false;
    render();
    await persistWatermarkLog();
  });
}
let PDF_LIB_PROMISE = null;
function loadPdfLib(){
  if(!PDF_LIB_PROMISE) PDF_LIB_PROMISE = import('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.esm.min.js');
  return PDF_LIB_PROMISE;
}
let FONTKIT_PROMISE = null;
function loadFontkit(){
  // pdf-lib's built-in StandardFonts (Helvetica etc.) can't encode Thai
  // characters at all — registering fontkit lets us embed real fonts
  // (below) instead. The watermark text itself is English/numbers today,
  // but account names could be Thai in the future, so this stays in place
  // as a safety net rather than reverting to StandardFonts.
  if(!FONTKIT_PROMISE) FONTKIT_PROMISE = import('https://cdn.jsdelivr.net/npm/@pdf-lib/fontkit@1.1.1/+esm');
  return FONTKIT_PROMISE;
}
// ฟอนต์ DilleniaUPC — ไฟล์ .ttf ที่ผู้ใช้อัปโหลดมาเอง (มีสิทธิ์ใช้งานอยู่แล้ว)
// ฝังเป็น base64 ไว้ในโค้ดตรงนี้เลย แทนการ fetch จากอินเทอร์เน็ต เพราะเป็น
// ฟอนต์ลิขสิทธิ์ ดึงจากแหล่งสาธารณะแบบ Sarabun (Google Fonts) ไม่ได้
// อัปเดต: ผู้ใช้ส่งไฟล์ตัวหนาจริง (DilleniaUPC Bold) มาให้แล้ว จึงฝังทั้งสอง
// น้ำหนักเป็นฟอนต์จริง ไม่ต้องพึ่งเทคนิค faux bold (วาดข้อความซ้ำเหลื่อมกัน)
// อีกต่อไป — ดู DILLENIA_HAS_REAL_BOLD ด้านล่าง
const DILLENIA_UPC_REGULAR_B64 = "";
const DILLENIA_UPC_BOLD_B64 = "";
const DILLENIA_HAS_REAL_BOLD = true;
function base64ToArrayBuffer(b64){
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}
let THAI_FONT_REGULAR_PROMISE = null;
function loadThaiFontRegular(){
  if(!THAI_FONT_REGULAR_PROMISE) THAI_FONT_REGULAR_PROMISE = Promise.resolve(base64ToArrayBuffer(DILLENIA_UPC_REGULAR_B64));
  return THAI_FONT_REGULAR_PROMISE;
}
let THAI_FONT_BOLD_PROMISE = null;
function loadThaiFontBold(){
  if(!THAI_FONT_BOLD_PROMISE) THAI_FONT_BOLD_PROMISE = Promise.resolve(base64ToArrayBuffer(DILLENIA_UPC_BOLD_B64));
  return THAI_FONT_BOLD_PROMISE;
}
// ตัวแบ่งคำภาษาไทยแบบมีพจนานุกรม (dictionary-based) ที่มากับเอนจิ้นเบราว์เซอร์เอง
// ผ่าน Intl.Segmenter — ใช้แทนการตัดตรงช่องว่างเฉยๆ เพราะข้อความไทยส่วนใหญ่
// เขียนติดกันไม่มีช่องว่างระหว่างคำ ถ้าใช้ได้ (เบราว์เซอร์ใหม่ๆ รองรับ) จะได้จุด
// ตัดบรรทัดที่ตรงกับคำจริงๆ ไม่ตัดกลางคำจนอ่านไม่ได้ความ
let THAI_WORD_SEGMENTER = undefined; // undefined = ยังไม่เช็ค, null = ใช้ไม่ได้
function getThaiWordSegmenter(){
  if(THAI_WORD_SEGMENTER === undefined){
    try{ THAI_WORD_SEGMENTER = new Intl.Segmenter('th', { granularity:'word' }); }
    catch(e){ THAI_WORD_SEGMENTER = null; }
  }
  return THAI_WORD_SEGMENTER;
}
// แตกข้อความหนึ่งบรรทัด (ไม่มี \n) ออกเป็น "อะตอม" สำหรับจัดเรียงลงบรรทัด —
// แต่ละอะตอมเป็นได้ทั้งคำ (ห้ามตัดกลางคำ) หรือช่องว่าง (ตัดบรรทัดตรงนี้ได้)
function atomizeForWrap(para){
  const seg = getThaiWordSegmenter();
  if(seg){
    try{
      const out = [];
      for(const s of seg.segment(para)) out.push({ text:s.segment, isSpace: /^\s+$/.test(s.segment) });
      return out;
    }catch(e){ /* ตกไปใช้วิธีสำรองด้านล่าง */ }
  }
  // สำรอง (เบราว์เซอร์ไม่รองรับ Intl.Segmenter): ตัดตรงช่องว่างเท่านั้น เหมือนเดิม
  const out = []; const re = /(\s+)|(\S+)/g; let m;
  while((m = re.exec(para))) out.push({ text:m[0], isSpace: !!m[1] });
  return out;
}
// ตัวช่วยแบ่ง "กลุ่มอักขระที่ต้องติดกันเสมอ" (grapheme cluster) — สำคัญมากกับ
// ภาษาไทย เพราะสระบน/ล่างและวรรณยุกต์เป็นอักขระ combining ที่ลอยอยู่บนตัวพยัญชนะ
// ฐาน ถ้าเผลอตัดขึ้นบรรทัดใหม่คั่นกลางระหว่างพยัญชนะฐานกับสระ/วรรณยุกต์ของมัน
// จะเห็นวรรณยุกต์/สระลอยเดี่ยวๆ อยู่ต้นบรรทัดถัดไป อ่านไม่ออก ดูเหมือน "ฟอนต์เพี้ยน"
// ทั้งที่จริงคือปัญหาจุดตัดบรรทัด ไม่ใช่ตัวฟอนต์ — ใช้ Intl.Segmenter('grapheme')
// (ไม่ต้องพึ่งพจนานุกรมภาษา รองรับกว้างกว่าการแบ่ง "คำ" มาก) เป็นหลัก และมี regex
// รวมอักขระ combining (\p{M}) เป็นตัวสำรองเผื่อเบราว์เซอร์เก่าไม่รองรับ
let GRAPHEME_SEGMENTER = undefined;
function getGraphemeSegmenter(){
  if(GRAPHEME_SEGMENTER === undefined){
    try{ GRAPHEME_SEGMENTER = new Intl.Segmenter(undefined, { granularity:'grapheme' }); }
    catch(e){ GRAPHEME_SEGMENTER = null; }
  }
  return GRAPHEME_SEGMENTER;
}
function toGraphemeClusters(str){
  const seg = getGraphemeSegmenter();
  if(seg){
    try{
      const out = [];
      for(const s of seg.segment(str)) out.push(s.segment);
      return out;
    }catch(e){ /* ตกไปใช้วิธีสำรองด้านล่าง */ }
  }
  // สำรอง: จับพยัญชนะ/อักขระฐานหนึ่งตัวพร้อมอักขระ combining (สระ/วรรณยุกต์) ที่
  // ตามหลังมันทั้งหมดไว้เป็นก้อนเดียว ไม่ให้หลุดออกจากกัน
  return str.match(/[\s\S]\p{M}*/gu) || [];
}
// word นี้กว้างเกิน maxWidth อยู่แล้วแม้อยู่บรรทัดเดียวลำพัง (พบยากมาก เช่นตัวเลข/
// URL ยาวๆ หรือข้อความไทยยาวๆ ที่ไม่มีช่องว่างให้ตัดคำ) — จำเป็นต้องตัดกลางคำจริงๆ
// ตัดตามความกว้างจริงที่วัดจากฟอนต์ แต่ตัดที่ขอบเขต "กลุ่มอักขระ" (grapheme cluster)
// เท่านั้น ไม่ตัดกลาง code point จนพยัญชนะกับสระ/วรรณยุกต์ของมันหลุดจากกัน
function breakWordByWidth(word, font, size, maxWidth, lines){
  let chunk = '';
  for(const ch of toGraphemeClusters(word)){
    const test = chunk + ch;
    if(chunk && font.widthOfTextAtSize(test, size) > maxWidth){
      lines.push(chunk);
      chunk = ch;
    } else {
      chunk = test;
    }
  }
  return chunk;
}
// รวมอะตอมวงเล็บ/เครื่องหมายคำพูดเปิด-ปิดเข้ากับคำข้างเคียงที่ติดกันจริง (ไม่มี
// ช่องว่างคั่น) เพื่อไม่ให้วงเล็บเปิด "(" ค้างอยู่ท้ายบรรทัดแยกจากเนื้อหาข้างใน
// หรือวงเล็บปิด ")" ไปโผล่เดี่ยวๆ ต้นบรรทัดถัดไป — นี่คือ "การจัดบรรทัดแปลกๆ"
// ที่พบในคอลัมน์ผู้แก้ไข เช่น "ชื่อ Busayapongchai (" ขึ้นบรรทัดใหม่แล้วเจอ
// "Quality Manager)" วงเล็บเปิดเลยลอยค้างอยู่คนละบรรทัดกับข้อความข้างใน
const OPEN_BRACKET_ATOM = /^[(\[{“‘]+$/;
const CLOSE_BRACKET_ATOM = /^[)\]}”’]+$/;
function glueBracketAtoms(atoms){
  const step1 = [];
  for(let i=0;i<atoms.length;i++){
    const atom = atoms[i];
    if(!atom.isSpace && OPEN_BRACKET_ATOM.test(atom.text) && i+1<atoms.length && !atoms[i+1].isSpace){
      step1.push({ text: atom.text + atoms[i+1].text, isSpace:false });
      i++;
      continue;
    }
    step1.push(atom);
  }
  const step2 = [];
  for(let i=0;i<step1.length;i++){
    const atom = step1[i];
    if(!atom.isSpace && CLOSE_BRACKET_ATOM.test(atom.text) && step2.length && !step2[step2.length-1].isSpace){
      step2[step2.length-1] = { text: step2[step2.length-1].text + atom.text, isSpace:false };
      continue;
    }
    step2.push(atom);
  }
  return step2;
}
// ตัดบรรทัดข้อความให้พอดีกับความกว้างคอลัมน์ (สำหรับวาดตารางลง PDF ด้วย pdf-lib
// ซึ่งไม่มีระบบ text-wrap อัตโนมัติ) — เคารพการขึ้นบรรทัดใหม่ที่มีอยู่แล้วด้วย
// ใช้ atomizeForWrap ด้านบนแบ่งเป็นคำๆ ก่อน (แล้วรวมวงเล็บที่ติดกันด้วย
// glueBracketAtoms) แล้วค่อยแพ็คลงบรรทัดทีละคำ จึงตัดบรรทัดได้เฉพาะระหว่างคำ
// เท่านั้น (ไม่ตัดกลางคำจนความหมายเพี้ยนแบบก่อนหน้านี้)
// ยกเว้นกรณีคำเดียวกว้างเกินทั้งคอลัมน์จริงๆ ถึงจะจำเป็นต้องตัดกลางคำ
function wrapTextLines(text, font, size, maxWidth){
  const paragraphs = String(text||'').split('\n');
  const lines = [];
  paragraphs.forEach(para=>{
    const atoms = glueBracketAtoms(atomizeForWrap(para));
    if(!atoms.length){ lines.push(''); return; }
    let current = '';
    atoms.forEach(atom=>{
      if(atom.isSpace){
        const test = current + atom.text;
        if(!current || font.widthOfTextAtSize(test, size) <= maxWidth){
          current = test;
        } else {
          lines.push(current);
          current = ''; // ทิ้งช่องว่างที่ตกไปอยู่ต้นบรรทัดใหม่
        }
        return;
      }
      if(font.widthOfTextAtSize(atom.text, size) > maxWidth){
        if(current){ lines.push(current); current = ''; }
        current = breakWordByWidth(atom.text, font, size, maxWidth, lines);
        return;
      }
      const test = current + atom.text;
      if(!current || font.widthOfTextAtSize(test, size) <= maxWidth){
        current = test;
      } else {
        lines.push(current);
        current = atom.text;
      }
    });
    if(current) lines.push(current);
  });
  return lines.length ? lines : [''];
}
// ลดขนาดฟอนต์ลงทีละน้อยจนข้อความพอดีกับความกว้างที่กำหนดในบรรทัดเดียว
// ใช้กับคอลัมน์ที่ต้องการบังคับให้อยู่บรรทัดเดียวเสมอ (เช่นวันที่) แทนการตัดบรรทัด
function fitSizeToWidth(text, font, baseSize, maxWidth, minSize){
  minSize = minSize || 8;
  let size = baseSize;
  while(size > minSize && font.widthOfTextAtSize(text, size) > maxWidth){ size -= 0.5; }
  return size;
}
// วาดตาราง "ทะเบียนประวัติเอกสาร" ของเอกสาร d ต่อท้าย pdfDoc เป็นหน้าใหม่
// (ขึ้นหน้าใหม่อัตโนมัติถ้าตารางยาวเกินหนึ่งหน้า) ใช้ฟอนต์ไทยเดียวกับลายน้ำ
function appendRevLogPagesToPdf(pdfDoc, d, regularFont, boldFont, rgb){
  const rows = sortRevLogRows(d.revisionLog||[]);
  if(!rows.length) return; // ไม่มีประวัติให้แนบ
  const PAGE_W = 595.28, PAGE_H = 841.89; // A4
  const margin = 40;
  const usableW = PAGE_W - margin*2;
  const headers = [
    { key:'no',      label:'แก้ไขครั้งที่',        frac:0.08, align:'center', singleLine:true  },
    { key:'reqDate', label:'วันที่แก้ไข',           frac:0.13, align:'center', singleLine:true  },
    { key:'date',    label:'วันที่ประกาศใช้',       frac:0.13, align:'center', singleLine:true  },
    { key:'detail',  label:'รายละเอียดการแก้ไข',   frac:0.46, align:'left'                     },
    { key:'by',      label:'ผู้แก้ไข (ตำแหน่ง)',    frac:0.20, align:'left'                     },
  ];
  const colW = {}; headers.forEach(h=> colW[h.key] = usableW*h.frac);
  const colX = {}; let cx = margin; headers.forEach(h=>{ colX[h.key] = cx; cx += colW[h.key]; });
  const tableRight = margin + usableW;
  // ขนาด 14 สำหรับหัวตาราง/เนื้อหาในตารางทุกคอลัมน์ ส่วนหัวข้อเอกสาร (ชื่อเรื่อง
  // ด้านบนตาราง) แยกเป็นตัวหนา ขนาด 18 จัดกึ่งกลางหน้าต่างหาก — หัวตารางใช้ตัวหนา
  // จริง รายการในตารางตัวปกติ (regularFont/boldFont ที่รับเข้ามาคือฟอนต์ไทยที่ฝัง
  // อยู่แล้ว — ดูหมายเหตุเรื่อง DilleniaUPC ท้ายไฟล์นี้)
  const bodySize = 14, headSize = 14, titleSize = 18, lineH = 22, cellPad = 6;
  const MIN_DATE_SIZE = 9; // ขนาดต่ำสุดที่ยอมลดลงไปเพื่อให้วันที่อยู่บรรทัดเดียว
  let page = pdfDoc.addPage([PAGE_W, PAGE_H]);
  let y = PAGE_H - margin;
  const titleText = `ประวัติการแก้ไขเอกสาร${d.id ? ' — ' + d.id : ''}`;
  const titleWidth = boldFont.widthOfTextAtSize(titleText, titleSize);
  const titleX = margin + Math.max(0, (usableW - titleWidth) / 2);
  page.drawText(titleText, { x: titleX, y: y-titleSize, size: titleSize, font: boldFont, color: rgb(0,0,0) });
  y -= titleSize + 16;
  function drawGridAndBorder(rowH){
    page.drawRectangle({ x: margin, y: y-rowH, width: usableW, height: rowH, borderColor: rgb(0,0,0), borderWidth:0.75 });
    let vx = margin;
    headers.forEach(h=>{ page.drawLine({ start:{x:vx,y}, end:{x:vx,y:y-rowH}, thickness:0.35, color: rgb(0,0,0) }); vx += colW[h.key]; });
    page.drawLine({ start:{x:tableRight,y}, end:{x:tableRight,y:y-rowH}, thickness:0.35, color: rgb(0,0,0) });
  }
  // วาดข้อความ (หลายบรรทัดได้) ของคอลัมน์หนึ่ง โดยจัดกึ่งกลางแนวตั้งในแถว —
  // ใช้ทั้งกับหัวตารางและแถวข้อมูล กันปัญหาข้อความยาวเกินคอลัมน์แล้วล้นทับคอลัมน์ข้างๆ
  function drawCellLines(font, size, lines, key, align, rowH, faux){
    const blockH = lines.length*lineH;
    const startY = y - Math.max(0,(rowH-blockH)/2);
    lines.forEach((line,i)=>{
      const w = font.widthOfTextAtSize(line, size);
      const tx = align==='center' ? colX[key] + Math.max(cellPad,(colW[key]-w)/2) : colX[key] + cellPad;
      const ty = startY - (i+1)*lineH + (lineH-size)/2;
      page.drawText(line, { x: tx, y: ty, size, font, color: rgb(0,0,0) });
      // ไม่มีไฟล์ DilleniaUPC ตัวหนาจริง — วาดซ้ำเหลื่อมกัน 0.4pt เพื่อให้
      // เส้นหนาขึ้นเล็กน้อย (faux bold) จนกว่าจะมีไฟล์ตัวหนาจริงมาแทน
      if(faux) page.drawText(line, { x: tx+0.4, y: ty, size, font, color: rgb(0,0,0) });
    });
  }
  function drawHeaderRow(){
    const wrapped = {}; let maxLines = 1;
    headers.forEach(h=>{
      const lines = wrapTextLines(h.label, boldFont, headSize, colW[h.key]-cellPad*2);
      wrapped[h.key] = lines;
      if(lines.length > maxLines) maxLines = lines.length;
    });
    const rowH = maxLines*lineH + cellPad*2;
    drawGridAndBorder(rowH);
    headers.forEach(h=> drawCellLines(boldFont, headSize, wrapped[h.key], h.key, 'center', rowH, !DILLENIA_HAS_REAL_BOLD));
    y -= rowH;
  }
  drawHeaderRow();
  // เตรียมข้อความของทุกแถวไว้ล่วงหน้าก่อนวาดจริง — จำเป็นสำหรับขั้นตอนถัดไปที่
  // ต้องหาขนาดฟอนต์ "ค่าเดียว" ของคอลัมน์วันที่/ลำดับ โดยดูจากทุกแถวพร้อมกัน
  const allCellText = rows.map(r=> ({
    no: r.no || '',
    reqDate: r.reqDate ? fmtDateRevLog(r.reqDate) : '',
    date: r.date ? fmtDateRevLog(r.date) : '',
    detail: r.detail || '',
    by: (r.byLabel!=null ? r.byLabel : revLogByLabel(r.by)) || '',
  }));
  // คอลัมน์วันที่/ลำดับ (singleLine) ต้องใช้ "ขนาดฟอนต์เดียวกันทุกแถว" ไม่ใช่ลด
  // ขนาดทีละเซลล์ตามความยาวของตัวมันเอง — ไม่งั้นวันที่ที่ชื่อเดือนยาว (เช่น
  // "พฤศจิกายน") จะถูกย่อเล็กกว่าวันที่เดือนสั้น (เช่น "มีนาคม") ในคอลัมน์
  // เดียวกัน ทำให้แต่ละแถวดูขนาดไม่เท่ากัน — จึงหาขนาดที่เล็กที่สุดที่จำเป็น
  // ต่อการใส่ "ทุกแถว" ในคอลัมน์นั้นให้พอดีก่อน แล้วค่อยใช้ขนาดเดียวกันนี้กับ
  // ทุกแถวในคอลัมน์นั้น
  const uniformSize = {};
  headers.forEach(h=>{
    if(!h.singleLine) return;
    const maxW = colW[h.key]-cellPad*2;
    let size = bodySize;
    allCellText.forEach(cellText=>{
      const fit = fitSizeToWidth(cellText[h.key], regularFont, bodySize, maxW, MIN_DATE_SIZE);
      if(fit < size) size = fit;
    });
    uniformSize[h.key] = size;
  });
  rows.forEach((r,i)=>{
    const cellText = allCellText[i];
    const wrapped = {}; const sizes = {}; let maxLines = 1;
    headers.forEach(h=>{
      const maxW = colW[h.key]-cellPad*2;
      if(h.singleLine){
        // คอลัมน์วันที่/ลำดับ: บังคับบรรทัดเดียวเสมอ ใช้ขนาดฟอนต์เดียวกันทุก
        // แถวที่คำนวณไว้แล้วข้างบน (uniformSize) แทนการลดขนาดทีละเซลล์
        sizes[h.key] = uniformSize[h.key];
        wrapped[h.key] = [cellText[h.key]];
      } else {
        sizes[h.key] = bodySize;
        wrapped[h.key] = wrapTextLines(cellText[h.key], regularFont, bodySize, maxW);
      }
      if(wrapped[h.key].length > maxLines) maxLines = wrapped[h.key].length;
    });
    const rowH = maxLines*lineH + cellPad*2;
    if(y - rowH < margin){
      page = pdfDoc.addPage([PAGE_W, PAGE_H]);
      y = PAGE_H - margin;
      drawHeaderRow();
    }
    drawGridAndBorder(rowH);
    headers.forEach(h=> drawCellLines(regularFont, sizes[h.key], wrapped[h.key], h.key, h.align, rowH));
    y -= rowH;
  });
}
// หมายเหตุเรื่องฟอนต์ DilleniaUPC: ฟอนต์นี้เป็นฟอนต์ลิขสิทธิ์ที่แถมมากับ
// ชุดภาษาไทยของ Windows ไม่ใช่ฟอนต์โอเพนซอร์สแบบ Sarabun (ที่ใช้อยู่ตอนนี้
// และดึงมาจาก Google Fonts ได้ตรงๆ) เราจึงดึงไฟล์ฟอนต์นี้จากอินเทอร์เน็ตมาฝัง
// ใน PDF ให้โดยอัตโนมัติไม่ได้ — ถ้าต้องการให้ตารางนี้ใช้ DilleniaUPC จริงๆ
// ต้องแนบไฟล์ .ttf ของ DilleniaUPC (ตัวปกติและตัวหนา) ที่มีลิขสิทธิ์ใช้งานอยู่แล้ว
// มาให้ แล้วจะฝังไฟล์นั้นแทน Sarabun ในโค้ดนี้ให้

async function watermarkAndDownload(file, docId){
  const [{ PDFDocument, rgb, degrees }, fontkitModule, regularBytes, boldBytes] = await Promise.all([
    loadPdfLib(), loadFontkit(), loadThaiFontRegular(), loadThaiFontBold(),
  ]);
  const fontkit = fontkitModule.default || fontkitModule;
  const positionLabel = currentUser ? (ROLE_LABEL[currentUser.role] || currentUser.role) : '—';
  const fullName = currentUser ? currentUser.name : '—';
  const lines = [
    { text: 'CONTROLLED DOCUMENT', size: 36, bold: true },
    { text: `Issued by ${positionLabel} (${fullName}) | Issue date: ${fmtDate(Date.now())}`, size: 24, bold: false },
  ];
  const bytes = await file.arrayBuffer();
  const pdfDoc = await PDFDocument.load(bytes);
  pdfDoc.registerFontkit(fontkit);
  const regularFont = await pdfDoc.embedFont(regularBytes, { subset: true });
  const boldFont = await pdfDoc.embedFont(boldBytes, { subset: true });
  const angleDeg = 45;
  const angleRad = angleDeg * Math.PI / 180;
  const lineGap = 42; // baseline-to-baseline spacing between the two lines — scaled up to match the larger font sizes
  const pages = pdfDoc.getPages();
  // Shrink any line that would run wider than the page can comfortably show
  // — the role/name text (line 2) varies in length depending on who's
  // logged in, so a fixed size that fits "Yarapon Puttakot" could overflow
  // for a longer name. Uses the first page's dimensions as the reference so
  // every page in the document gets the same, consistent watermark size.
  if(pages.length){
    const { width: refWidth, height: refHeight } = pages[0].getSize();
    const maxTextWidth = Math.min(refWidth, refHeight) * 0.85;
    lines.forEach(line=>{
      const font = line.bold ? boldFont : regularFont;
      const w = font.widthOfTextAtSize(line.text, line.size);
      if(w > maxTextWidth){
        line.size = Math.max(8, line.size * (maxTextWidth / w));
      }
    });
  }
  pages.forEach(page=>{
    const { width, height } = page.getSize();
    const centerX = width / 2, centerY = height / 2;
    const n = lines.length;
    lines.forEach((line, i)=>{
      const font = line.bold ? boldFont : regularFont;
      const textWidth = font.widthOfTextAtSize(line.text, line.size);
      // this line's stacked offset in the local (unrotated) text frame —
      // first line above the block's center, subsequent lines below it
      const localY = (n-1)/2*lineGap - i*lineGap;
      const halfWidth = textWidth / 2;
      const halfHeight = line.size * 0.32;
      // rotate both the horizontal-centering offset and the vertical-stack
      // offset from local text space into page space, then anchor relative
      // to the page's true center point
      const x = centerX - (halfWidth*Math.cos(angleRad) - halfHeight*Math.sin(angleRad)) - localY*Math.sin(angleRad);
      const y = centerY - (halfWidth*Math.sin(angleRad) + halfHeight*Math.cos(angleRad)) + localY*Math.cos(angleRad);
      page.drawText(line.text, {
        x, y, size: line.size, font,
        color: rgb(0.5,0.5,0.5), opacity: 0.35,
        rotate: degrees(angleDeg),
      });
    });
  });
  const docObj = DOCUMENTS.find(x=>x.id===docId);
  if(docObj) appendRevLogPagesToPdf(pdfDoc, docObj, regularFont, boldFont, rgb);
  const outBytes = await pdfDoc.save();
  const blob = new Blob([outBytes], { type:'application/pdf' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `${docId}-controlled-watermarked.pdf`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}
function attachWatermarkHandlers(){
  const importBtn = document.getElementById('btnImportMasterList');
  if(importBtn){
    importBtn.addEventListener('click', async ()=>{
      if(!isDC()) return; // defense in depth — button only renders for DC anyway
      if(!confirm('นำเข้ารายการเอกสารหลักทั้งหมด?\n\nเอกสารที่มีสถานะ "ควบคุม"/"แจกจ่าย"/"สนับสนุน"/"ยกเลิก" จะถูกตั้งเป็น "อนุมัติแล้ว" ทันที โดยไม่ผ่านขั้นตอนอนุมัติในระบบ และใช้วันที่จัดทำ/ประกาศใช้ตามรายการหลัก\n\nเอกสารสถานะ "ยกเลิก" จะไม่แสดงในรายการเอกสาร — ย้ายไปคลังเอกสาร โฟลเดอร์ "เอกสารยกเลิก" แทน')) return;
      const statusEl = document.getElementById('importMlStatus');
      importBtn.disabled = true;
      if(statusEl) statusEl.textContent = 'กำลังนำเข้า...';
      const result = await runMasterListImport();
      importBtn.disabled = false;
      if(!result.ok){
        if(statusEl) statusEl.textContent = result.message;
        return;
      }
      if(statusEl) statusEl.textContent = `นำเข้าเสร็จแล้ว — อัปเดต ${result.updated} รายการ, เพิ่มใหม่ ${result.created} รายการ, ย้ายไปคลังเอกสาร (ยกเลิก) ${result.archived} รายการ`;
      render();
    });
  }
  const repairBtn = document.getElementById('btnRepairRevNumbers');
  if(repairBtn){
    repairBtn.addEventListener('click', async ()=>{
      if(!isDC()) return; // defense in depth
      const targets = findCorruptedRevDocs();
      if(!confirm(`ซ่อมแซมเลข Rev. ที่ผิดพลาด ${targets.length} รายการ (${targets.map(d=>d.id).join(', ')})?\n\nระบบจะแก้เลข Rev. ของแต่ละเอกสารให้เป็น Rev. ถัดจาก Rev. เดิมก่อนขอปรับปรุง (ตามที่ควรจะเป็นตั้งแต่แรก) และบันทึกไว้ในประวัติเอกสาร การซ่อมแซมนี้ไม่สามารถย้อนกลับได้`)) return;
      const statusEl = document.getElementById('repairRevStatus');
      repairBtn.disabled = true;
      if(statusEl) statusEl.textContent = 'กำลังซ่อมแซม...';
      const result = await repairCorruptedRevNumbers();
      repairBtn.disabled = false;
      if(statusEl) statusEl.textContent = `ซ่อมแซมเสร็จแล้ว — แก้ไข ${result.fixed} รายการ`;
      render();
    });
  }
  const manualOpenBtn = document.getElementById('btnWmManualOpen');
  if(manualOpenBtn) manualOpenBtn.addEventListener('click', ()=>{ state.wmManualModal = true; renderModalLayer(); });
  const typeSel = document.getElementById('wmType');
  const recipientField = document.getElementById('wmRecipientField');
  if(typeSel && recipientField){
    const syncRecipientVisibility = ()=>{ recipientField.style.display = typeSel.value === 'distribute' ? '' : 'none'; };
    typeSel.addEventListener('change', syncRecipientVisibility);
    syncRecipientVisibility();
  }
  document.querySelectorAll('[data-wm-toggle]').forEach(row=>{
    row.addEventListener('click', ()=>{
      const id = row.dataset.wmToggle;
      state.wmExpandedDoc = state.wmExpandedDoc===id ? null : id;
      render();
    });
  });
  document.querySelectorAll('[data-wm-recall]').forEach(recallBtn=>{
    recallBtn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      const entry = WATERMARK_LOG.find(x=>x.id===recallBtn.dataset.wmRecall);
      if(!entry) return;
      if(entry.recalled){
        entry.recalled = false; entry.recalledAt = null; entry.recalledBy = null;
      } else {
        entry.recalled = true; entry.recalledAt = Date.now(); entry.recalledBy = currentActorName();
      }
      render();
      await persistWatermarkLog();
    });
  });
  document.querySelectorAll('[data-wm-del-entry]').forEach(delBtn=>{
    delBtn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      if(!isDC()) return; // defense in depth
      if(!confirm('ลบรายการทะเบียนสำเนานี้? ลบแล้วกู้คืนไม่ได้')) return;
      WATERMARK_LOG = WATERMARK_LOG.filter(x=>x.id!==delBtn.dataset.wmDelEntry);
      render();
      await persistWatermarkLog();
    });
  });
  document.querySelectorAll('[data-wm-del-doc]').forEach(delBtn=>{
    delBtn.addEventListener('click', async (e)=>{
      e.stopPropagation();
      if(!isDC()) return; // defense in depth
      const id = delBtn.dataset.wmDelDoc;
      if(!confirm(`ลบทะเบียนสำเนาทั้งหมดของ ${id}? ลบแล้วกู้คืนไม่ได้`)) return;
      WATERMARK_LOG = WATERMARK_LOG.filter(x=>x.docId!==id);
      render();
      await persistWatermarkLog();
    });
  });
  const btn = document.getElementById('btnWatermark');
  if(!btn) return;
  btn.addEventListener('click', async ()=>{
    if(!currentUser) return; // must be logged in — everyone with an account can print/watermark
    const errEl = document.getElementById('wmError');
    const statusEl = document.getElementById('wmStatus');
    const docId = document.getElementById('wmDocId').value.trim();
    const fileInput = document.getElementById('wmFile');
    const file = fileInput && fileInput.files && fileInput.files[0];
    const typeSelEl = document.getElementById('wmType');
    const type = typeSelEl && typeSelEl.value === 'distribute' ? 'distribute' : 'download';
    const recipientInput = document.getElementById('wmRecipient');
    errEl.style.display = 'none';
    if(!docId){ errEl.textContent = 'เลือกรหัสเอกสารก่อน'; errEl.style.display='block'; return; }
    if(!file){ errEl.textContent = 'เลือกไฟล์ PDF ก่อน'; errEl.style.display='block'; return; }
    if(file.type !== 'application/pdf'){ errEl.textContent = 'รองรับเฉพาะไฟล์ PDF เท่านั้น'; errEl.style.display='block'; return; }
    if(type === 'distribute' && recipientInput && !recipientInput.value.trim()){ errEl.textContent = 'ระบุว่าแจกจ่ายให้ใคร เพื่อให้เรียกคืนได้ในภายหลัง'; errEl.style.display='block'; return; }
    btn.disabled = true;
    statusEl.textContent = 'กำลังติดลายน้ำ...';
    try{
      await watermarkAndDownload(file, docId);
      const actor = currentActorName();
      const recipient = (type === 'distribute' && recipientInput) ? recipientInput.value.trim() : '';
      const now = Date.now();
      WATERMARK_LOG.push({
        id: 'WM-' + now.toString(36) + Math.random().toString(36).slice(2,7),
        docId, by: actor, at: now, manual: false, note: '', recipient, type,
        recalled: false, recalledAt: null, recalledBy: null,
      });
      await persistWatermarkLog();
      statusEl.textContent = 'เสร็จแล้ว — ดาวน์โหลดไฟล์และบันทึกประวัติแล้ว';
      fileInput.value = '';
      if(recipientInput) recipientInput.value = '';
      render();
    } catch(e){
      console.error('watermark failed', e);
      statusEl.textContent = '';
      errEl.textContent = 'ติดลายน้ำไม่สำเร็จ: ' + (e && e.message ? e.message : e);
      errEl.style.display = 'block';
    }
    btn.disabled = false;
  });
}

// ============================================================
// ทะเบียนประวัติการแก้ไขเอกสาร (REVISION LOG)
// A small, editable table per document — แก้ไขครั้งที่ / วันที่ประกาศใช้ /
// รายละเอียดการแก้ไข — mirroring the printed cover-page table used on the
// physical/PDF document itself (see the reference image this feature was
// built from). Stored separately on d.revisionLog (not derived purely from
// comments/groupHistoryByRequest) so DC can freely edit/add rows without
// touching the automatic audit trail. buildAutoRevLogRows() below can
// still pull a best-guess starting point from that audit trail on demand.
// ============================================================
function escapeHtml(s){
  return String(s==null?'':s).replace(/[&<>"']/g, ch=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[ch]));
}
// วันที่แบบเดิมที่ใช้ทั่วทั้งแอป: "DD/MM/YYYY" (ปี พ.ศ.) — คงรูปแบบนี้ไว้
// สำหรับทุกจุดยกเว้นทะเบียนประวัติเอกสาร (ดู fmtDateRevLog ด้านล่าง)
function fmtDate(ts){
  if(!ts) return '';
  const dt = new Date(ts);
  if(isNaN(dt.getTime())) return '';
  const d = String(dt.getDate()).padStart(2,'0');
  const m = String(dt.getMonth()+1).padStart(2,'0');
  const y = dt.getFullYear()+543;
  return `${d}/${m}/${y}`;
}
function fmtDateTime(ts){
  if(!ts) return '';
  const dt = new Date(ts);
  if(isNaN(dt.getTime())) return '';
  const hh = String(dt.getHours()).padStart(2,'0');
  const mm = String(dt.getMinutes()).padStart(2,'0');
  return `${fmtDate(ts)} ${hh}:${mm}`;
}
// วันที่แบบไทยเต็ม: "วัน เดือนเต็ม ปี พ.ศ." เช่น 2 มีนาคม 2564
// ใช้เฉพาะในตาราง "ทะเบียนประวัติเอกสาร" (บนหน้าจอ + ไฟล์ Word ที่ส่งออก)
// จุดอื่นๆ ในแอปยังคงใช้ fmtDate/fmtDateTime แบบสไลาช์ตามเดิม
const TH_MONTHS = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน',
                    'กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
// แปลงค่าวันที่ (ไม่ว่าจะเป็น timestamp แบบเก่า หรือสตริง "YYYY-MM-DD" ที่
// บันทึกแบบใหม่แล้ว) ให้กลายเป็นสตริง "YYYY-MM-DD" เสมอ — ใช้เป็นค่ากลาง
// สำหรับฟิลด์ reqDate/date ของทะเบียนประวัติเอกสาร เพื่อไม่ต้องแปลงผ่าน
// Date object ซ้ำไปมา (ต้นตอของบั๊กวันที่ลดลงทุกครั้งที่แก้ไข-บันทึก
// เพราะการแปลง timestamp <-> string ผ่าน timezone ซ้ำหลายรอบ)
function toISODateStr(val){
  if(!val) return '';
  if(typeof val === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(val)) return val;
  const dt = new Date(val);
  if(isNaN(dt.getTime())) return '';
  const y = dt.getFullYear();
  const m = String(dt.getMonth()+1).padStart(2,'0');
  const d = String(dt.getDate()).padStart(2,'0');
  return `${y}-${m}-${d}`;
}
function fmtDateRevLog(val){
  const iso = toISODateStr(val);
  if(!iso) return '';
  const [y, m] = iso.split('-').map(Number);
  const day = Number(iso.slice(8,10));
  return `${day} ${TH_MONTHS[m-1]} ${y+543}`;
}
// Converts a stored timestamp to the "YYYY-MM-DD" string a <input
// type="date"> expects, using LOCAL date parts (getFullYear/getMonth/
// getDate) rather than .toISOString() (which is always UTC). Mixing the
// two is exactly what was causing the revision-log dates to silently
// shift back a day every time the row was re-opened for editing: dates
// are stored as local midnight (new Date(value+'T00:00:00').getTime()),
// but Thailand is UTC+7, so local midnight is 17:00 UTC the PREVIOUS
// day — .toISOString().slice(0,10) was reading that previous-day date
// back into the input.
function toDateInputValue(ts){
  if(!ts) return '';
  const dt = new Date(ts);
  const y = dt.getFullYear();
  const m = String(dt.getMonth()+1).padStart(2,'0');
  const day = String(dt.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
}
// Best-guess rows derived from the existing comment trail: one row for the
// original "จองเลขเอกสาร" (Rev.0) and one per "ขอปรับปรุงจาก Rev.X เป็น
// Rev.Y" request, using each request's own note as the detail text.
// Two separate dates are tracked: "reqDate" (วันที่แก้ไข) is the moment the
// request/draft was actually created — the ขั้นที่ 1 comment's own
// timestamp, i.e. when the requester submitted it — and never changes
// after that. "date" (วันที่ประกาศใช้) is the effective/publish date: it
// starts equal to reqDate but gets superseded once the request reaches
// "ขั้นที่ 6: DC เผยแพร่เอกสาร" (falls back to the request date if the
// document is still mid-workflow and hasn't published yet).
// "by" on each row is the account that actually submitted that request
// (comment's own .by — set to the logged-in actor at the time, see e.g.
// the ขั้นที่ 1 comment pushes above), not necessarily the current user.
// "byLabel" is a FROZEN snapshot of that person's name + position at the
// moment the row is pulled in (via revLogByLabel below) — not recomputed
// from the live USERS table on every render. This matters because a
// person's role can change later (e.g. QM promoted to LM): without
// freezing, every historical row would silently start showing their
// CURRENT title instead of the title they actually held when they made
// that request. DC can still hand-correct byLabel per row (edit mode) for
// entries pulled in before this snapshot existed, or whenever the
// recorded position needs a retroactive fix.
// "no" is assigned sequentially (00, 01, 02, ...) in chronological order
// rather than reusing the target Rev. number, since the two don't always
// line up (e.g. a document whose Rev. numbering has gaps or a non-numeric
// scheme). DC can still hand-edit any "no" after it's pulled in.
function buildAutoRevLogRows(d){
  const comments = (d.comments||[]).slice(); // stored oldest → newest
  const rows = [];
  let currentRow = null;
  comments.forEach(c=>{
    let m;
    if((m = c.text.match(/^ขั้นที่ 1: จองเลขเอกสาร\s*—\s*(.*)$/))){
      currentRow = { reqDate:c.time, date:c.time, detail: m[1] || 'จัดทำเอกสารใหม่', byLabel: revLogByLabel(c.by) };
      rows.push(currentRow);
    } else if((m = c.text.match(/^ขั้นที่ 1: ขอปรับปรุงจาก Rev\.(.*?) เป็น Rev\.([^\s—]+)\s*—\s*(.*)$/))){
      currentRow = { reqDate:c.time, date:c.time, detail: m[3] || `ขอปรับปรุงจาก Rev.${m[1]} เป็น Rev.${m[2]}`, byLabel: revLogByLabel(c.by) };
      rows.push(currentRow);
    } else if(/^ขั้นที่ 6: DC เผยแพร่เอกสาร/.test(c.text) && currentRow){
      currentRow.date = c.time; // publish/effective date supersedes the request date
    }
  });
  rows.forEach((r,i)=>{ r.no = String(i).padStart(2,'0'); }); // 00, 01, 02, 03...
  return rows;
}
// Display label for a revision-log "ผู้แก้ไข" cell: the requester's name
// plus their role/position (e.g. "Yarapon Puttakot (Document Control)"),
// looked up from USERS/ROLE_LABEL by name since only the name is stored
// on the comment. Falls back gracefully if the account can no longer be
// matched (e.g. name changed later). Only used to compute the INITIAL
// snapshot (byLabel) when a row is first pulled in — see the note above
// buildAutoRevLogRows for why the result is then frozen on the row
// instead of being recomputed from this function every render.
function revLogByLabel(name){
  if(!name) return '';
  const u = USERS.find(x=>x.name===name);
  const role = u ? (ROLE_LABEL[u.role]||u.role) : '';
  return role ? `${name} (${role})` : name;
}
function sortRevLogRows(rows){
  return rows.slice().sort((a,b)=>{
    const na = parseFloat(a.no), nb = parseFloat(b.no);
    if(!isNaN(na) && !isNaN(nb) && na!==nb) return na-nb;
    if(!isNaN(na) && !isNaN(nb)) return toISODateStr(a.date).localeCompare(toISODateStr(b.date));
    return String(a.no||'').localeCompare(String(b.no||''));
  });
}
function newRevLogId(){ return 'rl_' + Date.now().toString(36) + Math.random().toString(36).slice(2,7); }
// Pulls in any auto-derived row (see above) not already present as an
// 'auto' row with the same แก้ไขครั้งที่ — never touches/duplicates rows
// DC has already added or hand-edited.
async function mergeAutoRevLogRows(d){
  d.revisionLog = Array.isArray(d.revisionLog) ? d.revisionLog : [];
  const auto = buildAutoRevLogRows(d);
  let added = 0;
  auto.forEach(a=>{
    const exists = d.revisionLog.some(r=>r.source==='auto' && String(r.no)===String(a.no));
    if(!exists){
      d.revisionLog.push({ id:newRevLogId(), no:a.no, date:a.date, reqDate:a.reqDate||null, detail:a.detail, byLabel:a.byLabel||'', source:'auto' });
      added++;
    }
  });
  d.revisionLog = sortRevLogRows(d.revisionLog);
  if(added){ d.lastUpdated = Date.now(); await persistDocs(); }
  return added;
}
// Reads whatever is currently typed in the edit-mode inputs back into
// state.revLogDraftRows, so add/remove-row buttons (which re-render the
// whole modal) never lose in-progress edits.
function syncRevLogDraftFromDom(){
  if(!state.revLogDraftRows) return;
  document.querySelectorAll('[data-revlog-row]').forEach(rowEl=>{
    const id = rowEl.dataset.revlogRow;
    const row = state.revLogDraftRows.find(r=>r.id===id);
    if(!row) return;
    const noEl = rowEl.querySelector('[data-f="no"]');
    const reqDateEl = rowEl.querySelector('[data-f="reqdate"]');
    const dateEl = rowEl.querySelector('[data-f="date"]');
    const detailEl = rowEl.querySelector('[data-f="detail"]');
    const byLabelEl = rowEl.querySelector('[data-f="bylabel"]');
    if(noEl) row.no = noEl.value.trim();
    if(reqDateEl) row.reqDate = reqDateEl.value || null;
    if(dateEl) row.date = dateEl.value || null;
    if(detailEl) row.detail = detailEl.value;
    if(byLabelEl) row.byLabel = byLabelEl.value.trim();
  });
}
// "ทะเบียนประวัติเอกสาร" — rendered as a section INSIDE the existing
// History modal (historyModalView), not a separate popup, so it always
// opens together with the document's History.
function revLogSectionView(d){
  const editing = state.revLogEditing;
  const rows = editing ? (state.revLogDraftRows || []) : sortRevLogRows(d.revisionLog||[]);
  const canEdit = isDC();
  return `
  <div class="panel" style="margin-top:20px; box-shadow:none; border:1px solid var(--line); padding:16px;">
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; margin-bottom:10px;">
      <div class="panel-title" style="margin-bottom:0;">ทะเบียนประวัติเอกสาร</div>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        ${editing ? `
          <button class="btn ghost" id="revLogCancelEditBtn">ยกเลิก</button>
          <button class="btn primary" id="revLogSaveBtn">${ic('check')} บันทึก</button>
        ` : `
          <button class="btn ghost" id="revLogExportBtn">${ic('download')} ส่งออกไฟล์ Word</button>
          ${canEdit ? `<button class="btn ghost" id="revLogAutoFillBtn">${ic('history')} ดึงจากประวัติอัตโนมัติ</button>` : ''}
          ${canEdit ? `<button class="btn ghost" id="revLogEditBtn">${ic('edit')} แก้ไข</button>` : ''}
        `}
      </div>
    </div>
    <div class="table-wrap" data-scroll-id="revLogTable" style="overflow-x:auto; max-height:320px; overflow-y:auto;">
      <table class="dtable revlog-table">
        <thead><tr><th>แก้ไขครั้งที่</th><th>วันที่แก้ไข</th><th>วันที่ประกาศใช้</th><th>รายละเอียดการแก้ไข</th><th>ผู้แก้ไข (ตำแหน่ง)</th>${editing ? '<th style="width:40px;"></th>' : ''}</tr></thead>
        <tbody>
          ${rows.length ? rows.map(r=> editing ? `
          <tr data-revlog-row="${r.id}">
            <td><input data-f="no" value="${escapeHtml(r.no||'')}"></td>
            <td><input data-f="reqdate" type="date" value="${toISODateStr(r.reqDate)}"></td>
            <td><input data-f="date" type="date" value="${toISODateStr(r.date)}"></td>
            <td><textarea data-f="detail">${escapeHtml(r.detail||'')}</textarea></td>
            <td><input data-f="bylabel" value="${escapeHtml(r.byLabel!=null ? r.byLabel : revLogByLabel(r.by))}" placeholder="ชื่อ (ตำแหน่ง)"></td>
            <td style="text-align:center;"><button type="button" class="btn ghost" style="padding:4px 8px;" data-revlog-del="${r.id}">${ic('trash')}</button></td>
          </tr>` : `
          <tr>
            <td style="text-align:center;">${escapeHtml(r.no||'—')}</td>
            <td style="text-align:center; white-space:nowrap;">${r.reqDate ? fmtDateRevLog(r.reqDate) : '—'}</td>
            <td style="text-align:center; white-space:nowrap;">${r.date ? fmtDateRevLog(r.date) : '—'}</td>
            <td style="white-space:pre-wrap;">${escapeHtml(r.detail||'')}${r.source==='auto' ? ' <span class="revlog-src-auto">(อัตโนมัติ)</span>' : ''}</td>
            <td style="white-space:nowrap;">${escapeHtml((r.byLabel!=null ? r.byLabel : revLogByLabel(r.by))||'—')}</td>
          </tr>`).join('') : `<tr><td colspan="${editing?6:5}" style="text-align:center; padding:16px 0; color:var(--ink-500);">ยังไม่มีประวัติการแก้ไข</td></tr>`}
        </tbody>
      </table>
    </div>
    ${editing ? `<button type="button" class="btn ghost" id="revLogAddRowBtn" style="margin-top:10px;">${ic('plus')} เพิ่มแถว</button>` : ''}
    ${!editing && !canEdit ? `<div style="font-size:11px; color:var(--ink-500); margin-top:10px;">เฉพาะ Document Control เท่านั้นที่แก้ไขทะเบียนนี้ได้</div>` : ''}
  </div>`;
}
function wireRevLogSection(d){
  const exportBtn = document.getElementById('revLogExportBtn');
  if(exportBtn) exportBtn.addEventListener('click', ()=> exportRevLogToWord(d));

  const autoFillBtn = document.getElementById('revLogAutoFillBtn');
  if(autoFillBtn) autoFillBtn.addEventListener('click', async ()=>{
    autoFillBtn.disabled = true;
    const added = await mergeAutoRevLogRows(d);
    renderModalLayer();
    if(!added) alert('ไม่มีประวัติใหม่ให้ดึงเพิ่ม (รายการที่มีอยู่ครบแล้ว)');
  });

  const editBtn = document.getElementById('revLogEditBtn');
  if(editBtn) editBtn.addEventListener('click', ()=>{
    if(!isDC()) return; // defense in depth
    state.revLogDraftRows = sortRevLogRows(d.revisionLog||[]).map(r=>({ ...r }));
    state.revLogEditing = true;
    renderModalLayer();
  });

  const cancelEditBtn = document.getElementById('revLogCancelEditBtn');
  if(cancelEditBtn) cancelEditBtn.addEventListener('click', ()=>{
    state.revLogEditing = false;
    state.revLogDraftRows = null;
    renderModalLayer();
  });

  const addRowBtn = document.getElementById('revLogAddRowBtn');
  if(addRowBtn) addRowBtn.addEventListener('click', ()=>{
    syncRevLogDraftFromDom();
    // number picks up where the last row left off (00, 01, 02...); by
    // defaults to whoever's adding the row (DC), same "detect from the
    // logged-in account" logic used for the auto-pulled rows.
    const nextNo = String(state.revLogDraftRows.length).padStart(2,'0');
    state.revLogDraftRows.push({ id:newRevLogId(), no:nextNo, reqDate:toISODateStr(Date.now()), date:null, detail:'', byLabel:revLogByLabel(currentActorName()), source:'manual' });
    renderModalLayer();
  });

  document.querySelectorAll('[data-revlog-del]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      syncRevLogDraftFromDom();
      const id = btn.dataset.revlogDel;
      state.revLogDraftRows = state.revLogDraftRows.filter(r=>r.id!==id);
      renderModalLayer();
    });
  });

  const saveBtn = document.getElementById('revLogSaveBtn');
  if(saveBtn) saveBtn.addEventListener('click', async ()=>{
    if(!isDC()) return; // defense in depth
    syncRevLogDraftFromDom();
    // drop rows the user added but never actually filled in
    const cleaned = state.revLogDraftRows.filter(r=> (r.no && r.no.trim()) || (r.detail && r.detail.trim()) || r.date || r.reqDate);
    d.revisionLog = sortRevLogRows(cleaned);
    d.lastUpdated = Date.now();
    state.revLogEditing = false;
    state.revLogDraftRows = null;
    renderModalLayer();
    await persistDocs();
  });
}
// Exports the ทะเบียนฯ table as a .doc file that opens directly in Microsoft
// Word, laid out to match the printed cover-page table this feature is
// based on (title + 3-column bordered table, Thai document-control style).
// Uses the classic "HTML saved as .doc" approach rather than a real .docx
// binary — no external library/CDN dependency needed, and Word opens/
// renders it identically; the person can Save As .docx from within Word if
// they specifically need the modern format.
// MS Word's own HTML-import layout engine does NOT honor CSS word-break/
// word-wrap for scripts without spaces — a long run of Thai text with no
// space characters is treated as a single unbreakable "word" and is left
// to overflow the table cell (visually overlapping the next column) rather
// than wrapping. Real space characters are the only break opportunity Word
// reliably respects, so we insert an invisible zero-width space (U+200B)
// between consecutive Thai consonants (never between a consonant and a
// following combining vowel/tone mark, so diacritics never get separated
// from their base letter) to give Word real places to break the line.
function withThaiBreakOpportunities(s){
  return String(s==null?'':s).replace(/([\u0E01-\u0E2E])(?=[\u0E01-\u0E2E])/g, '$1\u200B');
}
function exportRevLogToWord(d){
  const rows = sortRevLogRows(d.revisionLog||[]);
  const MIN_ROWS = 20; // pad with blank rows so the printed table has room for future entries, same as the reference template
  const blankNeeded = Math.max(0, MIN_ROWS - rows.length);
  const title = `ประวัติการแก้ไขเอกสาร${(typeof docTypeLabel==='function' ? docTypeLabel(d) : '') || ''}`;
  const bodyRows = rows.map(r=>`
    <tr>
      <td style="text-align:center;">${escapeHtml(r.no||'')}</td>
      <td style="text-align:center;">${r.reqDate ? fmtDateRevLog(r.reqDate) : ''}</td>
      <td style="text-align:center;">${r.date ? fmtDateRevLog(r.date) : ''}</td>
      <td>${escapeHtml(withThaiBreakOpportunities(r.detail||'')).replace(/\n/g,'<br>')}</td>
      <td>${escapeHtml(withThaiBreakOpportunities((r.byLabel!=null ? r.byLabel : revLogByLabel(r.by))||''))}</td>
    </tr>`).join('');
  const blankRows = Array.from({length:blankNeeded}).map(()=>`
    <tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>`).join('');
  const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)}</title>
<!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument></xml><![endif]-->
<style>
  @page{ size:A4; margin:2cm; }
  body, table, td, th{ font-family:'DilleniaUPC','Angsana New','TH SarabunPSK',serif; }
  body{ font-size:16pt; line-height:1.5; }
  h1{ text-align:center; font-size:18pt; font-weight:bold; margin-bottom:16pt; line-height:1.3; }
  table{ border-collapse:collapse; width:100%; table-layout:fixed; }
  td, th{ border:1px solid #000; padding:6px 8px; font-size:16pt; line-height:1.5; vertical-align:top; word-wrap:break-word; overflow-wrap:break-word; word-break:break-all; }
  th{ text-align:center; font-weight:bold; }
</style>
</head>
<body>
  <h1>${escapeHtml(title)}</h1>
  <table>
    <colgroup>
      <col style="width:8%;">
      <col style="width:13%;">
      <col style="width:13%;">
      <col style="width:46%;">
      <col style="width:20%;">
    </colgroup>
    <thead><tr><th>แก้ไขครั้งที่</th><th>วันที่แก้ไข</th><th>วันที่ประกาศใช้</th><th>รายละเอียดการแก้ไข</th><th>ผู้แก้ไข (ตำแหน่ง)</th></tr></thead>
    <tbody>${bodyRows}${blankRows}</tbody>
  </table>
</body>
</html>`;
  const blob = new Blob(['\ufeff', html], { type:'application/msword' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${d.id}_ประวัติการแก้ไขเอกสาร.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(()=> URL.revokeObjectURL(url), 3000);
}

